using Dogity.Domain.Sports;
using Microsoft.EntityFrameworkCore;

namespace Dogity.Infrastructure.Persistence.Seed;

/// <summary>
/// Obedience (Paket O1, 2026-10-21): die FCI-Klassen 1 bis 3 und die
/// nationalen Einsteigerklassen von VDH (Beginner, Senioren), ÖKV (Beginner,
/// Senior) und SKG (Beginners).
///
/// Eine Sportart <c>OBEDIENCE</c> für alle acht Ordnungen, mit gemeinsamen
/// Übungen: "Freifolge" ist eine Übung der Sportart und hängt an allen acht
/// Ordnungen; was je Klasse abweicht (Dauer, Distanz, Hörzeichen, Positionen,
/// Punkte), steht in den Hinweisen der Ordnungs-Übung mit Seitenangabe. Nur die
/// drei Übungen, die es in keiner FCI-Klasse gibt (Verhalten gegenüber anderen
/// Hunden, Sprung über eine Hürde, Bringen auf ebener Erde), sind national.
///
/// Geltungsbereich je Ordnung ausdrücklich: Die FCI-Ordnungen gelten überall
/// (<c>Ueberall</c>), die übrigen tragen "DE", "AT" bzw. "CH". Die Sportart
/// steht deshalb in <see cref="FciKatalog.InternationaleSportarten"/> - wie
/// die BH, unter der es auch eine nationale (ÖKV-)Ordnung gibt - und ist in
/// jedem Land sichtbar. Englische Namen und Texte (<see cref="FciKatalog"/>,
/// <see cref="FciTexteEn"/>) gibt es nur für die FCI-Ordnungen und die
/// Übungen, die sie führen.
///
/// Quellen (siehe docs/PO_VERIFIKATION.md, Abschnitt "Obedience"): jede
/// Ordnung und Übung nennt die Seite, wie sie im Dokument steht ("S. 14";
/// beim VDH ist es die Nummer im Seitenfuß des Auszugs). Die Texte sind eigene
/// Beschreibungen, keine Kopie der Ordnungen. Unklares ist nicht geglättet,
/// sondern so benannt, wie es im Dokument steht (z. B. Übung 6 der
/// VDH-Beginner-Klasse: Tabelle "Abrufen aus dem Quadrat", Kapitel "Abrufen").
///
/// Bestand: Der Seeder läuft auch gegen eine Datenbank, in der es schon eine
/// Sportart "Obedience" gibt. Gefunden wird die globale Sportart (ohne Verein)
/// mit dem Code <c>OBEDIENCE</c>; fehlt sie, wird eine globale Sportart mit dem
/// Namen "Obedience" unter ihrem Code mitgenutzt (nicht doppelt angelegt). Eine
/// Vereinssportart gleichen Namens oder Codes bleibt unberührt. Vorhandene
/// Übungen werden wie überall nur ergänzt, nie überschrieben.
/// </summary>
public static partial class SportCatalogSeeder
{
    /// <summary>Geltungsbereich der VDH-Ordnungen (ISO 3166-1 alpha-2).</summary>
    private const string Deutschland = FciKatalog.Deutschland;

    private const string QuelleFciObedience = "https://www.fci.be/medias/OBE-REG-COB-123-20250101-en-19742.pdf";
    private const string QuelleVdhObedience = "https://www.vdh.de/fileadmin/media/hundesport/obedience/2025/VDH_Pruefungsordnung_Obedience_deutsch_1-1-2025.pdf";
    private const string QuelleSkgObedience = "https://www.tkamo.ch/media/files/Obedience_Reglement_2025_DE.pdf";

    /// <summary>
    /// Der Code der Sportart, in die Obedience gehört: <c>OBEDIENCE</c>, bei
    /// einem Bestand ohne diese Sportart aber der Code einer gleichnamigen
    /// globalen Sportart. So entsteht keine zweite Sportart "Obedience".
    /// </summary>
    private static async Task<string> ObedienceSportCodeAsync(ApplicationDbContext db)
    {
        if (await db.Sports.IgnoreQueryFilters().AnyAsync(s => s.Code == FciKatalog.ObedienceCode && s.ClubId == null))
            return FciKatalog.ObedienceCode;

        var gleichnamig = await db.Sports
            .Where(s => s.ClubId == null && s.Name.ToLower() == "obedience")
            .OrderBy(s => s.Code)
            .Select(s => s.Code)
            .FirstOrDefaultAsync();
        return gleichnamig ?? FciKatalog.ObedienceCode;
    }

    private static async Task<Sport> SeedObedienceAsync(ApplicationDbContext db)
    {
        var obedience = await SeedSportAsync(db, await ObedienceSportCodeAsync(db), "Obedience",
        [
